import { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronDown, Search, Menu, X, LogIn, Facebook, Mail, Phone } from 'lucide-react';
import { SearchContext } from '../../context/SearchContext';

export default function Header() {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [isEmailLoginModalOpen, setIsEmailLoginModalOpen] = useState(false);
  const [isPhoneLoginModalOpen, setIsPhoneLoginModalOpen] = useState(false);
  const [isSignupModalOpen, setIsSignupModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const { selectedLocation, setSelectedLocation, selectedCategory, setSelectedCategory } = useContext(SearchContext);

  const navigate = useNavigate();

  const toggleDropdown = () => setIsDropdownOpen((prev) => !prev);
  const toggleMobileMenu = () => setIsMobileMenuOpen((prev) => !prev);
  const toggleLoginModal = () => setIsLoginModalOpen((prev) => !prev);
  const toggleEmailLoginModal = () => {
    setIsEmailLoginModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };
  const togglePhoneLoginModal = () => {
    setIsPhoneLoginModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };
  const toggleSignupModal = () => {
    setIsSignupModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };
  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false);
  };
  const handleCategoryChange = (category) => setSelectedCategory(category);
  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) navigate(`/search?query=${searchQuery}`);
  };

  return (
    <header className="bg-white mt-0">
      <div className="container mx-auto px-4 py-4 flex items-center">
        {/* Left Section: Logo */}
        <div className="flex items-center space-x-6">
          <Link to="/">
            <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
          </Link>
          <div className="relative hidden md:block">
            <button
              onClick={toggleDropdown}
              className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
            >
              <span>{selectedLocation}</span> <ChevronDown size={16} />
            </button>
            {isDropdownOpen && (
              <div className="absolute mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
                <ul>
                  {['All', 'Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                    <li
                      key={location}
                      onClick={() => handleLocationChange(location)}
                      className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                    >
                      {location}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>

        {/* Middle Section: Search Bar */}
        <div className="flex-grow mx-6">
          <form onSubmit={handleSearch} className="flex items-center bg-gray-100 rounded-md">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 bg-transparent focus:outline-none"
            />
            <button type="submit" className="p-2 bg-red-500 text-white rounded-r-md">
              <Search size={24} />
            </button>
          </form>
        </div>

        {/* Right Section: Options */}
        <div className="flex items-center space-x-4">
          <button onClick={toggleMobileMenu} className="block md:hidden text-gray-600 hover:text-gray-800">
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <button onClick={toggleSignupModal} className="hidden md:block text-gray-600 hover:text-red-500">
            Sign up
          </button>
          <button onClick={toggleLoginModal} className="hidden md:block text-gray-600 hover:text-red-500">
            Login
          </button>
          <Link to="/sell" className="hidden md:block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700">
            Sell
          </Link>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-white border-t px-4 py-4">
          <div className="space-y-4">
            <button onClick={toggleSignupModal} className="block text-gray-600 hover:text-red-500">
              Sign up
            </button>
            <button onClick={toggleLoginModal} className="block text-gray-600 hover:text-red-500">
              Login
            </button>
            <Link to="/sell" className="block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700">
              Sell
            </Link>
          </div>
        </div>
      )}

      {/* Modals */}
      {isLoginModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md">
            <button onClick={toggleLoginModal} className="absolute top-2 right-2 text-2xl">
              X
            </button>
            <h2 className="text-center mb-4">Login</h2>
            <button onClick={toggleEmailLoginModal} className="w-full py-2 bg-gray-100 rounded-md">
              Login with Email
            </button>
            <button onClick={togglePhoneLoginModal} className="w-full py-2 bg-gray-100 rounded-md mt-2">
              Login with Phone
            </button>
          </div>
        </div>
      )}
    </header>
  );
}
